package api

import (
	"testing"

	"github.com/n42blockchain/N42/common/hexutil"
	"github.com/n42blockchain/N42/common/types"
)

func TestCodexDebugExecutionPayloadHash(t *testing.T) {
	payload := &ExecutionPayloadV1{
		ParentHash:    types.HexToHash("0xcb4c993e716e052eac1d566becae628b24d0f490c4efaff9f4153b8cf092a5f0"),
		FeeRecipient:  types.HexToAddress("0x2adc25665018aa1fe0e6bc666dac8fc2697ff9ba"),
		StateRoot:     types.HexToHash("0xa5952800ccfd6fb0f438bc9cac82071cea585ba084472c75cae25ee7273b24d8"),
		ReceiptsRoot:  types.HexToHash("0xc8038a257bc3638440aac969600ee8eb705a6c7faece0527e7db051ff4e819c9"),
		LogsBloom:     hexutil.MustDecode(""),
		PrevRandao:    types.Hash{},
		BlockNumber:   hexutil.Uint64(1),
		GasLimit:      hexutil.Uint64(0x07270e00),
		GasUsed:       hexutil.Uint64(0x599c),
		Timestamp:     hexutil.Uint64(0x3e8),
		ExtraData:     hexutil.MustDecode("0x00"),
		BaseFeePerGas: hexutil.Uint64(7),
		BlockHash:     types.HexToHash("0xad1de5abf144c6ba0434f18693010b9deabf0cac48dc15c717ffcfdcafc4982c"),
		Transactions: []hexutil.Bytes{
			hexutil.MustDecode(""),
		},
	}
	blk, err := executionPayloadV1ToBlock(payload)
	if err != nil {
		t.Fatalf("executionPayloadV1ToBlock() error = %v", err)
	}
	t.Logf("txroot=%s", blk.TxHash())
	t.Logf("blockhash=%s", ethCompatibleBlockHash(blk, &params.ChainConfig{LondonBlock: big.NewInt(0)}))
}
